"""Installed swfte-sdk client module (trimmed)."""
from __future__ import annotations

import os
from typing import Any, Dict, Optional
from urllib.parse import quote

import requests


class _Workflows:
    def __init__(self, client: "SwfteClient") -> None:
        self._client = client

    def invoke(self, workflow_id: str, inputs: Optional[Dict[str, Any]] = None) -> Dict[str, Any]:
        return self._client._api_request("POST", f"/v2/workflows/{quote(workflow_id, safe='')}/invoke", json=inputs or {})


class SwfteClient:
    def __init__(self, api_key: Optional[str] = None, api_base_url: str = "https://api.swfte.com/agents") -> None:
        self.api_key = api_key or os.environ.get("SWFTE_API_KEY")
        self.api_base_url = api_base_url
        self.workflows = _Workflows(self)

    def _api_request(self, method: str, path: str, json: Any = None) -> Any:
        resp = requests.request(method, self.api_base_url + path, json=json, headers={"Authorization": f"Bearer {self.api_key}"})
        resp.raise_for_status()
        return resp.json()


def _selftest() -> None:
    SwfteClient().workflows.invoke("wf_Vend0r1", {"ping": True})
